Definition BSEGS : list Segment := AsanUbsan.M.loaded_segments.

Definition AT_B : atable :=
  {| img_lo := 0x10000; img_hi := 0x663000; n_res := 4; shadow_off := 0x7fff8000;
     a_entry := 0x4b350; rw_lo := 0x102000; rw_len := 0x561000; ph_addr_z := 0x10040; ph_ent_z := 56; ph_num_z := 11;
     x_imemset := 0x809a8; x_imemcpy := 0x8092c; x_memset := 0xfc38c; x_memcpy := 0xfbf88; x_memiszero := 0x80ed8;
     x_istrncpy := 0x80dd4; x_sealed := 0x11aae; x_popfree := 0x51a00;
     x_sniff := 0; sniff_tab := 0; sniff_cell := 0;
     x_envscan := 0xed2e0; x_envscan_k := 0xed2ec; x_pnscan := 0xed3a4; x_pnscan_k := 0xed3b0;
     stops_more := [0x7706c; 0x77080; 0x77094; 0x7ca24; 0x8b0bc] (* [comment removed for export] *) |}.


(* [comment removed for export] *)
Definition XN_B (id : nat) (args : list expr) (cs : acs) : option acs :=
  match id with
  | 210 => node_nameword NXS cs args
  | 200 => summary_fill AT_B NXS cs (x_imemset AT_B) 256
  | 201 => summary_fill AT_B NXS cs (x_memset AT_B) two64
  | 202 => summary_copy BSEGS AT_B NXS cs (x_imemcpy AT_B)
  | 203 => summary_copy BSEGS AT_B NXS cs (x_memcpy AT_B)
  | 204 => summary_miz AT_B NXS cs
  | 205 => summary_istrncpy AT_B NXS cs
  | 206 => node_envscan AT_B cs
  | 207 => node_pnscan AT_B NXS cs
  | 208 => node_layout cs args
  | 27 => Some cs
  | _ => None
  end%nat.

Definition chkB (IT : itab) (HS : nat -> option acs) (cs : acs) (p : plan) : cres :=
  checkA BSEGS IT AT_B NXS LIMIT_S ISP_S XN_B XE_S XB_S XA_S AP.XT0 HS KC_S true BFUEL_S FUEL_S None cs p.
Definition cert_okB (IT : itab) (HS : nat -> option acs) (cs : acs) (p : plan) : bool :=
  match chkB IT HS cs p with COk s => fullT s | _ => false end.

Definition both_init_S : acs := init_acs3 AT_B.
